SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET time_zone = "+00:00";
SET FOREIGN_KEY_CHECKS = 0;

-- Struktur tabel
--

CREATE TABLE `siswa` (
  `id` int NOT NULL,
  `user_id` int DEFAULT NULL,
  `rombel_id` int DEFAULT NULL,
  `nis` varchar(20) DEFAULT NULL,
  `nisn` varchar(20) DEFAULT NULL,
  `nik` varchar(20) DEFAULT NULL,
  `nama_lengkap` varchar(100) NOT NULL,
  `email_siswa` varchar(100) DEFAULT NULL,
  `jenis_kelamin` enum('L','P') DEFAULT NULL,
  `tempat_lahir` varchar(50) DEFAULT NULL,
  `tanggal_lahir` date DEFAULT NULL,
  `agama` varchar(20) DEFAULT NULL,
  `status_dalam_keluarga` varchar(30) DEFAULT NULL,
  `anak_ke` int DEFAULT NULL,
  `alamat_siswa` text,
  `rt` varchar(5) DEFAULT NULL,
  `rw` varchar(5) DEFAULT NULL,
  `dusun` varchar(50) DEFAULT NULL,
  `kelurahan` varchar(50) DEFAULT NULL,
  `kecamatan` varchar(50) DEFAULT NULL,
  `kode_pos` varchar(10) DEFAULT NULL,
  `jenis_tinggal` varchar(50) DEFAULT NULL,
  `alat_transportasi` varchar(50) DEFAULT NULL,
  `no_telp_rumah` varchar(20) DEFAULT NULL,
  `no_hp` varchar(20) DEFAULT NULL,
  `asal_sekolah` varchar(100) DEFAULT NULL,
  `skhun` varchar(50) DEFAULT NULL,
  `penerima_kps` enum('Ya','Tidak') DEFAULT 'Tidak',
  `no_kps` varchar(50) DEFAULT NULL,
  `no_peserta_un` varchar(50) DEFAULT NULL,
  `no_seri_ijazah` varchar(50) DEFAULT NULL,
  `penerima_kip` enum('Ya','Tidak') DEFAULT 'Tidak',
  `nomor_kip` varchar(50) DEFAULT NULL,
  `nama_di_kip` varchar(100) DEFAULT NULL,
  `nomor_kks` varchar(50) DEFAULT NULL,
  `no_registrasi_akta` varchar(50) DEFAULT NULL,
  `layak_pip` enum('Ya','Tidak') DEFAULT 'Tidak',
  `alasan_layak_pip` varchar(100) DEFAULT NULL,
  `kebutuhan_khusus` varchar(50) DEFAULT 'Tidak ada',
  `no_kk` varchar(20) DEFAULT NULL,
  `diterima_dikelas` varchar(10) DEFAULT NULL,
  `tgl_diterima` date DEFAULT NULL,
  `status_siswa` enum('Aktif','Lulus','Pindah','Keluar') DEFAULT 'Aktif',
  `berat_badan` int DEFAULT NULL COMMENT 'dalam kg',
  `tinggi_badan` int DEFAULT NULL COMMENT 'dalam cm',
  `lingkar_kepala` int DEFAULT NULL COMMENT 'dalam cm',
  `jml_saudara_kandung` int DEFAULT NULL,
  `jarak_ke_sekolah` varchar(10) DEFAULT NULL COMMENT 'dalam KM',
  `ekskul_1` int DEFAULT NULL,
  `ekskul_2` int DEFAULT NULL,
  `ekskul_3` int DEFAULT NULL,
  `foto_siswa` varchar(255) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--

-- Data
--


-- --------------------------------------------------------

--

-- Index
--
ALTER TABLE `siswa`
  ADD PRIMARY KEY (`id`),
  ADD UNIQUE KEY `user_id` (`user_id`),
  ADD UNIQUE KEY `nisn` (`nisn`),
  ADD UNIQUE KEY `email_siswa` (`email_siswa`),
  ADD KEY `rombel_id` (`rombel_id`);

--

-- AUTO_INCREMENT
--
ALTER TABLE `siswa`
  MODIFY `id` int NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=670;

--

SET FOREIGN_KEY_CHECKS = 1;
